#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    long long countCaesarPairs(vector<string>& words) {
        auto normalize = [](const string& w) -> string {
            int offset = w[0] - 'a';
            string res = "";
            for (char c : w) {
                res += (char)((c - 'a' - offset + 26) % 26 + 'a');
            }
            return res;
        };
        unordered_map<string, long long> counts;
        for (const auto& w : words) counts[normalize(w)]++;
        long long ans = 0;
        for (const auto& [k, m] : counts) {
            ans += m * (m - 1) / 2;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countCaesarPairs(String[] words) {
        Map<String, Long> counts = new HashMap<>();
        for (String w : words) {
            String norm = normalize(w);
            counts.put(norm, counts.getOrDefault(norm, 0L) + 1);
        }
        long ans = 0;
        for (long m : counts.values()) {
            ans += m * (m - 1) / 2;
        }
        return ans;
    }

    private String normalize(String w) {
        int offset = w.charAt(0) - 'a';
        char[] arr = new char[w.length()];
        for (int i = 0; i < w.length(); i++) {
            arr[i] = (char)((w.charAt(i) - 'a' - offset + 26) % 26 + 'a');
        }
        return new String(arr);
    }
}

var countCaesarPairs = function(words) {
    function normalize(w) {
        const offset = w.charCodeAt(0) - 97;
        let res = '';
        for (let i = 0; i < w.length; i++) {
            res += String.fromCharCode((w.charCodeAt(i) - 97 - offset + 26) % 26 + 97);
        }
        return res;
    }
    const counts = new Map();
    for (const w of words) {
        const norm = normalize(w);
        counts.set(norm, (counts.get(norm) || 0) + 1);
    }
    let ans = 0;
    for (const m of counts.values()) {
        ans += Math.floor(m * (m - 1) / 2);
    }
    return ans;
};
